# Launcher for Claude Code, generated by modules/home/ai/claude/code.nix.
#
# 1. Loads the subscription token for this process only (optional).
# 2. With isolation enabled, runs Claude Code in a bubblewrap sandbox that
#    contains nothing but an allowlist: the Nix store, a filtered /etc, the
#    current project, Claude's own state and explicitly listed paths. Every
#    command Claude runs inherits the same view. Shares, secrets, SSH keys,
#    the rest of $HOME and runtime sockets simply do not exist inside.
#
# Configuration arrives as environment variables set by the Nix wrapper:
#   CLAUDE_REAL TOKEN_FILE EXPIRES_FILE ISOLATE TRUST_PROJECT BWRAP POLICY_FILE
#   PROJECT_ROOTS_FILE RO_PATHS_FILE RW_PATHS_FILE PASS_ENV_FILE
#   (files with one entry per line)
set -euo pipefail

if [ -n "$TOKEN_FILE" ] && [ -z "${CLAUDE_CODE_OAUTH_TOKEN-}" ] && [ -r "$TOKEN_FILE" ]; then
    CLAUDE_CODE_OAUTH_TOKEN="$(<"$TOKEN_FILE")"
    export CLAUDE_CODE_OAUTH_TOKEN
fi

if [ -n "$EXPIRES_FILE" ] && [ -r "$EXPIRES_FILE" ]; then
    expires="$(<"$EXPIRES_FILE")"
    if expires_at="$(date -d "$expires" +%s 2>/dev/null)" &&
        [ "$(date +%s)" -gt "$((expires_at - 30 * 24 * 60 * 60))" ]; then
        echo "warning: Claude subscription token expires on $expires; renew it with 'claude setup-token'." >&2
    fi
fi

if [ "$ISOLATE" != 1 ]; then
    exec "$CLAUDE_REAL" "$@"
fi

expand() {
    case "$1" in
    \~) printf '%s\n' "$HOME" ;;
    \~/*) printf '%s\n' "$HOME/${1#\~/}" ;;
    *) printf '%s\n' "$1" ;;
    esac
}

# Only start inside an allowed project root, never in $HOME or on a share.
project="$(pwd -P)"
allowed=0
while IFS= read -r root; do
    [ -n "$root" ] || continue
    root="$(realpath -m "$(expand "$root")")"
    case "$project/" in
    "$root"/*) allowed=1 ;;
    esac
done <"$PROJECT_ROOTS_FILE"

if [ "$allowed" != 1 ] || [ "$project" = "$HOME" ] || [ "$project" = / ]; then
    echo "claude: refusing to start in $project" >&2
    echo "claude: allowed project roots:" >&2
    while IFS= read -r root; do echo "  $root" >&2; done <"$PROJECT_ROOTS_FILE"
    exit 1
fi

# The launcher's own configuration is exported by the Nix wrapper; keep it
# in plain shell variables before the environment is cleaned.
real_claude="$CLAUDE_REAL"
sandbox_tool="$BWRAP"
policy="$POLICY_FILE"
ro_list="$RO_PATHS_FILE"
rw_list="$RW_PATHS_FILE"
auto_trust="$TRUST_PROJECT"

# Drop every environment variable that is not explicitly passed through,
# e.g. SOPS_AGE_KEY, SSH_AUTH_SOCK or cloud credentials. Unsetting here keeps
# values off any command line.
keep=" HOME USER LOGNAME PATH TERM COLORTERM LANG LC_ALL LC_CTYPE TZ CLAUDE_CODE_OAUTH_TOKEN $(tr '\n' ' ' <"$PASS_ENV_FILE")"
while IFS= read -r name; do
    case "$keep" in
    *" $name "*) ;;
    *) unset "$name" 2>/dev/null || true ;;
    esac
done < <(env -0 | while IFS= read -r -d '' pair; do printf '%s\n' "${pair%%=*}"; done)

args=(
    --unshare-all
    --share-net
    --die-with-parent
    --hostname claude-sandbox
    --proc /proc
    --dev /dev
    --tmpfs /tmp
    --tmpfs /run
    --ro-bind /nix/store /nix/store
    --ro-bind-try /run/current-system /run/current-system
    --ro-bind-try /bin /bin
    --ro-bind-try /usr /usr
    --tmpfs /etc
)

# /etc entries are mostly symlinks into /etc/static on NixOS; recreate them
# as symlinks and bind real files read-only. Skip what Claude never needs.
for entry in /etc/* /etc/.[!.]*; do
    [ -e "$entry" ] || [ -L "$entry" ] || continue
    case "${entry#/etc/}" in
    claude-code | ssh | sudoers | sudoers.d | shadow | gshadow | sops* | NetworkManager | wireguard | openvpn) continue ;;
    esac
    if [ -L "$entry" ]; then
        args+=(--symlink "$(readlink "$entry")" "$entry")
    else
        args+=(--ro-bind "$entry" "$entry")
    fi
done

# Policy that Claude Code cannot override from inside.
args+=(--ro-bind "$policy" /etc/claude-code/managed-settings.json)
args+=(--remount-ro /etc)

# A blank home with only Claude's state, then the project itself.
mkdir -p "$HOME/.claude"
[ -s "$HOME/.claude.json" ] || printf '{}\n' >"$HOME/.claude.json"
chmod 600 "$HOME/.claude.json"

# Skip the trust dialog for this project. Rewrite in place: running
# sessions keep ~/.claude.json bind-mounted and must see the same file.
if [ "$auto_trust" = 1 ]; then
    trusted="$(jq --arg p "$project" '.projects[$p].hasTrustDialogAccepted = true' "$HOME/.claude.json")" &&
        printf '%s\n' "$trusted" >"$HOME/.claude.json"
fi
args+=(
    --tmpfs "$HOME"
    --bind "$HOME/.claude" "$HOME/.claude"
    --bind "$HOME/.claude.json" "$HOME/.claude.json"
)

while IFS= read -r path; do
    [ -n "$path" ] || continue
    path="$(expand "$path")"
    if [ -e "$path" ]; then args+=(--ro-bind "$path" "$path"); fi
done <"$ro_list"

while IFS= read -r path; do
    [ -n "$path" ] || continue
    path="$(expand "$path")"
    if [ -e "$path" ]; then args+=(--bind "$path" "$path"); fi
done <"$rw_list"

args+=(--bind "$project" "$project" --chdir "$project")

exec "$sandbox_tool" "${args[@]}" -- "$real_claude" "$@"
